  "sim.auto.5": "자동: {y}",
  "sim.auto.6": "제{term}대 {orgName} 제{num}회 {typeLabel}",
  "sim.auto.7": "다음: 임시회",
  "sim.auto.8": "혁명적 사회주의",
  "sim.auto.9": "사회주의",
