  "sim.bill.1": "국가재건특별법 제1조",
  "sim.bill.2": "재건",
  "sim.bill.3": "긴급",
  "sim.bill.4": "국가 재건을 위해 필요한 모든 조치를 취할 수 있다.\n집행부는 의회의 동의 없이 긴급 법령을 발동할 수 있다.",
  "sim.bill.5": "모든 원에 같은 비율",
  "sim.bill.6": "· {seats}석",
  "sim.bill.7": "과반",
  "sim.bill.8": "특별다수(2/3)",
  "sim.bill.9": "법안 제목을 입력하세요.",
  "sim.bill.10": "가결된 법안만 개정안을 발의할 수 있습니다.",
  "sim.bill.11": "개정안",
  "sim.bill.12": "📝 개정 대상:",
  "sim.bill.13": "(제{v}판)",
  "sim.bill.15": "계엄령으로 의회가 정지된 상태에서는 국회로 상정할 수 없습니다.",
  "sim.bill.16": "(위원회 심사 중)",
  "sim.bill.17": "법안이 수정되었습니다.",
  "sim.bill.18": "하원✔",
  "sim.bill.19": "하원✘",
  "sim.bill.20": "상원✔",
  "sim.bill.21": "상원✘",
  "sim.bill.22": "삼원✔",
  "sim.bill.23": "삼원✘",
  "sim.bill.24": "{vetoHolderLabel}의 거부권을 행사해 이 법안을 최종 부결시킵니다. 계속하시겠습니까?",
  "sim.bill.25": "✔ 최종 가결",
  "sim.bill.26": "✘ 최종 부결",
  "sim.bill.27": "🛑 {vetoHolderLabel} 거부권 행사",
  "sim.bill.28": "⏳ {vetoHolderLabel} 서명 대기",
  "sim.bill.29": "대기 중",
  "sim.bill.30": "✔통과",
