  "sim.core.14": "{pm} 이름",
  "sim.core.15": "현재 선출 방식: {president} 임명제 — {president2}이 후보를 지명하면 의회 심의를 거쳐 {pm}으로 확정됩니다",
  "sim.core.16": "현재 선출 방식: 다수당 방식 — 기준 원({presElectionChamberBasis})의 다수당 대표가 자동으로 {pm}이 됩니다",
  "sim.core.17": "현재 선출 방식: 총리직선제 — 선거 > 총선 탭에서 \"총리 선거\"로 개표하세요",
  "sim.core.18": "🔒 내각 불신임으로 총리가 공석입니다 — 직접 지정하거나, 아래 \"고정 해제\"로 현재 다수당 대표를 새 총리로 반영하세요.",
