  "sim.core.24": "{nomineeName}에 대한 {pm} 임명동의안이 국가 > 입법 탭에 상정되었습니다.",
  "sim.core.25": "건설적 불신임제에서는 후임 총리를 함께 지명해야 합니다.\n후임 총리 이름을 입력하세요.",
  "sim.core.26": "건설적 불신임안 — 후임 {pmLabel}: {name}",
  "sim.core.27": "내각 불신임안",
  "sim.core.28": "현 {pmLabel}를 불신임하고 {name}{name2}을(를) 후임 {pmLabel2}로 선출한다.",
  "sim.core.29": "불신임안",
  "sim.core.30": "건설적불신임",
  "sim.core.31": "건설적 불신임안(후임 {pmLabel}: {name})이 국가 > 입법 탭에 상정되었습니다.\n가결되면 {name2}이(가) 곧바로 새 {pmLabel2}가 됩니다.",
  "sim.core.32": "내각 불신임안이 국가 > 입법 탭에 상정되었습니다.",
  "sim.core.33": "-- 후임 {pmLabel} 소속 정당 --",
  "sim.core.35": "후임 {pmLabel} 이름",
  "sim.core.36": "건설적 불신임안",
  "sim.core.37": "가결되면 지명한 후임이 곧바로 새 {pmLabel}가 되고, 기존 내각(부{pmLabel2}·국무위원)은 물러납니다 — 공석이 생기지 않습니다",
  "sim.core.38": "가결되면 국가 > 입법 탭에서 확인할 수 있으며, 통과 시 현재 {pmLabel}가 해임됩니다",
  "sim.core.39": "건설적 불신임안이 가결되어 {name}이(가) 새 {pm}가 되었습니다.\n기존 내각은 물러났으니 내각 > 내각에서 새 국무위원을 채워 주세요.",
  "sim.core.40": "직책 (예: 외교부 장관)",
