  "sim.core.50": "{senate} 해산",
  "sim.core.51": "{house} 해산",
  "sim.core.52": "이미 선포된 해산의 대상은 바꿀 수 없습니다.\n총선을 반영해 해제한 뒤 다시 고르세요.",
  "sim.core.53": "먼저 권한 주체를 지정하세요.",
  "sim.core.54": "{key}은 스스로 해제할 수 없습니다.\n선거 > 총선에서 새 선거를 반영해야 해제됩니다.",
  "sim.core.55": "{key}을(를) 선포합니다. 계속하시겠습니까?",
  "sim.core.56": "의회 전체가 이미 해산된 상태에서는 해산권을 분할할 수 없습니다.\n총선을 반영해 해제한 뒤 다시 시도하세요.",
  "sim.core.57": "상원 또는 하원이 이미 해산된 상태에서는 해산권 분할을 끌 수 없습니다.\n총선을 반영해 해제한 뒤 다시 시도하세요.",
  "sim.core.58": "계엄 해제 결의안",
  "sim.core.59": "계엄해제",
  "sim.core.60": "계엄 해제 결의안이 국가 > 입법 탭에 자동으로 상정되었습니다.\n의회가 가결하면 계엄령이 해제됩니다.",
  "sim.core.61": "! 계엄령 선포 중 — 의회 활동 정지 !",
