  "sim.core.70": "심의할 법안을 먼저 선택하세요.",
  "sim.core.71": "국무회의에 참여할 인원이 없습니다 (모든 자리가 공석입니다).",
  "sim.core.72": "표결한 국무위원이 없습니다.\n내각 디스플레이에서 각 인물의 찬성·반대·기권을 먼저 표시하세요.",
  "sim.core.73": "가결",
  "sim.core.74": "부결",
  "sim.core.75": "국무회의 표결 결과 — 찬성 {yea} · 반대 {nay} · 기권 {v} (총 {totalParticipants}인)\n\n『{title}』이(가) {pass}됩니다. 확정하시겠습니까?",
  "sim.core.76": "『{title}』이(가) 국무회의 의결로 {pass}되었습니다.",
  "sim.core.77": "계엄령으로 의회가 정지된 상태에서는 표결을 진행할 수 없습니다.\n법안은 국무회의를 통해 통과시킬 수 있습니다.",
  "sim.core.78": "▌ 비상 권한",
  "sim.core.79": "! {lbl} 선포됨 (총선으로만 해제) !",
