  "sim.coup.32": "{type}를 일으킵니다 — 주도: {leaderName}, 성공 확률 {chance}%. 계속하시겠습니까?",
  "sim.coup.33": "주도 정당 없이 군사평의회 집권 (숨겨진 정부 형태: 군정)",
  "sim.coup.34": "군사평의회 의장 교체 ({chairName} → {role})",
