  "sim.coup.45": "{president} {name} 축출 (공석)",
  "sim.coup.46": "민정 이양 — 계엄령을 해제하고 의회 · 선거를 되살립니다. 쿠데타로 활동 금지된 정당은 복권되고, 대통령 · 총리는 다음 선거까지 공석입니다. 계속하시겠습니까?",
  "sim.coup.47": "계엄령 해제 · 의회 활동 재개 · 선거 재개",
  "sim.coup.48": "대통령 · 총리 공석 (선거로 뽑음)",
  "sim.coup.49": "이미 군정입니다 — 내각 › 쿠데타의 \"민정 이양\"으로 벗어날 수 있어요.",
  "sim.coup.50": "군사평의회 의장이 될 군 지휘관이 없습니다 — 내각 › 군부에서 군 지휘부를 먼저 정하세요.",
  "sim.coup.51": "디버그 — 쿠데타 없이 바로 군정으로 바꿉니다 (의장: {leaderName}). 계속하시겠습니까?",
  "sim.coup.52": "디버그 모드로 바로 바꿈",
