  "sim.district.1": "{name}이(가) 하원과 다른 지역구 지도를 쓰도록 나눕니다.\n지금 지도를 복사해 그대로 이어 쓰며, 이후 {name2} 지도를 따로 올릴 수 있습니다. 계속하시겠습니까?",
  "sim.district.2": "{name}이(가) 다시 하원 지도를 함께 쓰도록 합칩니다.\n하원 지도에 없는 {name2} 지역구의 데이터(의석 · 성향 · 당선자)는 사라집니다. 계속하시겠습니까?",
  "sim.district.3": "{districtChamber}의 지역구 데이터가 새 지도로 대체됩니다.\n(이름·의석 수·성향·당선자 정보 포함) 계속하시겠습니까?",
  "sim.district.4": "기존 지역구 데이터가 모두 새 지도로 대체됩니다.\n(이름·의석 수·성향·당선자 정보 포함) 계속하시겠습니까?",
  "sim.district.5": "파일을 읽지 못했습니다.",
  "sim.district.6": "지금 지역구가 모두 이 지역구 프리셋으로 바뀝니다 — 지도 · 이름 · 의석 수 · 인구 · 권역 (모든 원).\n정당 · 내각은 그대로이고, 지역구 성향 · 당선자 · 선거 결과는 비워집니다. 계속하시겠습니까?",
  "sim.district.7": "종합 프리셋(.hemi) 파일입니다.\n저장 창의 \"종합 프리셋 불러오기\"로 여세요. 여기서는 지역구 프리셋(.hemimap)과 맵 메이커 지도(.jsx)를 올립니다.",
  "sim.district.8": "지역구 프리셋(.hemimap)이나 맵 메이커 지도(.jsx)가 아닙니다.",
  "sim.district.9": "맵 메이커에서 내보낸 .jsx 파일에서 지역구로 쓸 도형을 찾을 수 없습니다.",
  "sim.district.10": "색상",
