  "sim.history.38": "왼쪽 의회 › 세력 변화에서 \"지금 의석 기록하기\"를 누르거나, 총선을 치러 의회에 반영하면 여기에 아래로 쌓여요.",
  "sim.history.39": "굵은 칸은 그 시점의 집권 세력 · ▲▼는 바로 앞 기록과의 차이 (최근 8개)",
  "sim.history.40": "🔁 정당 승계",
  "sim.history.41": "당명 · 색 바꾸기 (승계)",
  "sim.history.42": "한나라당 → 새누리당처럼 같은 정당이 이름 · 색을 바꿉니다. 의석 · 의원 · 연정은 그대로 이어지고, 그 시점이 기록돼 \"당 변화\"에 표시돼요.",
  "sim.history.43": "새 이름",
