  "sim.history.45": "승계 관계 잇기",
  "sim.history.46": "서로 다른 정당을 앞 정당 → 뒤 정당으로 잇습니다 (해산 뒤 후신 · 합당 · 분당). 지금까지의 기록 바로 다음 기록에서 앞 정당 줄이 뒤 정당 줄로 합쳐져요 — 합당이면 앞 정당은 해산하거나 의석을 0으로 두세요.",
  "sim.history.47": "잇기",
  "sim.history.48": "끊기",
  "sim.history.49": "정당 의석을 시점마다 기록해 세력이 어떻게 오르내렸는지(의석 변화), 정당이 어떻게 생기고 바뀌고 이어졌는지(당 변화) 봅니다. 총선 결과를 의회에 반영하면 자동으로 기록돼요.",
  "sim.history.50": "📸 지금 의석 기록하기",
  "sim.history.51": "선거 기록에서 가져오기",
  "sim.history.52": "📊 오른쪽 시각 화면 \"세력 변화\" 탭에서 의석 변화 · 당 변화 도표를 아래로 스크롤하며 봐요.",
