  "sim.people.74": "이민자 성향 · 이민자 지지율에서 이민자 성향을 따로 정합니다. 이민자가 투표하는 선거에서는 지역구마다 시민 · 이민자 수만큼 섞어 개표해요 (총선 비례 · 대선은 전국 수로).",
  "sim.people.75": "꺼져 있으면 이민자 성향은 시민 성향과, 이민자 지지율은 시민 지지율과 같은 값으로 묶이고 이민자도 시민과 같은 성향으로 투표합니다. 시민 · 인구 수는 따로예요.",
  "sim.people.76": "지역구 인구가 없습니다 — 국가 › 지역구 지도에서 지역구마다 \"시민 / 인구\"를 적으세요.",
