  "sim.podium.6": "반원 가운데에 의장석(단상과 의장)을 그립니다. \"항상 표시\"면 반원 화면에도 늘 보이고, 봉쇄 돌파 · 의장석 점거 애니메이션에도 나옵니다.",
  "sim.podium.7": "반원 가운데(의석 수 · 로고 위)에 의장석(단상과 의장)을 그립니다.",
  "sim.politics.1": "동일 후보수 분배",
