  "sim.politics.6": "권역 · 지역구를 참여 정당의 지금 의석 비율대로 나눠 맡아요 (각자 상대적으로 강한 곳부터).",
  "sim.politics.7": "현직 우선",
  "sim.politics.8": "지역구마다 지금 그 지역구를 가진(지난 선거 당선) 참여 정당이 다시 나섭니다. 현직이 없으면 지지율 1위. 대선 · 총리 선거는 현직 대통령 · 총리의 정당이 참여했으면 그 정당이에요.",
