  "sim.revolution.18": "{nm}헌법",
  "sim.revolution.19": "우리 국민은 독재에 맞서 일어선 혁명의 정신을 이어받아, 자유롭고 민주적인 기본 질서를 굳게 세우고 국민 모두의 존엄과 권리를 지키기 위하여 이 헌법을 제정한다.",
  "sim.revolution.20": "국민주권",
  "sim.revolution.21": "주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다.",
  "sim.revolution.22": "기본권",
  "sim.revolution.23": "모든 국민은 인간으로서의 존엄과 가치를 가지며, 국가는 개인이 가지는 불가침의 기본적 인권을 확인하고 이를 보장할 의무를 진다.",
  "sim.revolution.24": "복수정당제",
  "sim.revolution.25": "정당의 설립은 자유이며, 복수정당제는 보장된다.",
  "sim.revolution.26": "의회 의원과 국가 원수는 국민의 보통 · 평등 · 직접 · 비밀 선거로 뽑는다.",
  "sim.revolution.27": "권력 분립",
  "sim.revolution.28": "입법권은 의회에, 행정권은 정부에, 사법권은 법원에 속한다.",
  "sim.revolution.29": "계엄의 제한",
  "sim.revolution.30": "계엄은 의회의 동의 없이 60일을 넘길 수 없으며, 계엄 중에도 의회의 활동은 정지되지 아니한다.",
  "sim.revolution.31": "{nm}사회주의 헌법",
  "sim.revolution.32": "우리 나라",
  "sim.revolution.33": "{nm}는 {name}의 영도 아래 혁명으로 세워진 인민의 국가이다. 인민은 혁명의 위업을 이어 사회주의 건설을 완성하기 위하여 이 헌법을 채택한다.",
  "sim.revolution.34": "국가의 성격",
  "sim.revolution.35": "{nm}는 노동자 · 농민 · 근로 인텔리를 비롯한 전체 인민의 이익을 대표하는 사회주의 국가이다.",
  "sim.revolution.36": "당의 영도",
  "sim.revolution.37": "국가는 {name}의 영도 아래 모든 활동을 한다.",
  "sim.revolution.38": "통일전선",
  "sim.revolution.39": "국가는 혁명에 찬동하는 우당 및 사회단체와 통일전선을 이룬다.",
  "sim.revolution.40": "최고주권기관",
  "sim.revolution.41": "최고인민회의는 국가의 최고주권기관이다.",
  "sim.revolution.42": "국가주석",
  "sim.revolution.43": "국가주석은 국가의 수반이며, 당의 총서기가 겸임한다.",
  "sim.revolution.44": "최고인민회의 대의원은 통일전선이 추천한 단일 후보에 대한 찬반 투표로 선출한다.",
  "sim.revolution.45": "{nm}평의회 헌법",
  "sim.revolution.46": "{nm}는 {names}의 혁명 연합이 함께 세운 노동자 · 인민의 평의회 국가이다. 인민은 혁명의 길을 두고 자유롭게 토론하고 겨루며 사회주의를 건설하기 위하여 이 헌법을 채택한다.",
  "sim.revolution.47": "{nm}는 노동자 · 농민 · 근로 인민의 평의회가 다스리는 사회주의 국가이다.",
