  "sim.royal.26": "국체",
  "sim.royal.27": "{nm}는 입헌군주국이다. 군주는 국가와 국민 통합의 상징이며 국정에 관한 실권을 가지지 아니한다.",
  "sim.royal.28": "국민주권",
  "sim.royal.29": "주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다.",
  "sim.royal.30": "행정권은 내각에 속하며, 총리는 의회의 신임에 기초한다.",
  "sim.royal.31": "우리 국민은 군주제를 폐지하고, 국민 모두가 주권자인 공화국을 세우며 자유와 평등의 질서를 지키기 위하여 이 헌법을 제정한다.",
