  "sim.unrecovered.36": "오른쪽 지도에서 지역구를 차례로 눌러 \"{name}\"로 칠합니다 (같은 종류로 칠한 곳을 다시 누르면 지움). 다시 \"칠하는 중\"을 누르면 끝납니다.",
  "sim.unrecovered.37": "\"칠하기\"를 누른 뒤 오른쪽 지도에서 지역구를 차례로 눌러 여러 곳을 한 번에 칠하세요. 칠하기 도구를 끈 채 지역구를 누르면 아래에서 종류를 고를 수 있습니다.",
  "sim.unrecovered.38": "종류를 추가하고 \"칠하기\"로 오른쪽 지도에서 지역구를 칠하세요.",
