  "sim.vassals.9": "독립국",
  "sim.vassals.10": "— 해방되어 본국에서 떨어져 나간 땅 · 국가 › 종속국에서 관리",
  "sim.vassals.11": "종속국",
  "sim.vassals.12": "— 본국에 딸린 나라의 땅 (본국 선거 · 의석에서 빠짐) · 국가 › 종속국에서 관리",
  "sim.vassals.13": "\"{name}\" {name2}에 지지율이 있는 정당이 없습니다. 정당을 추가하거나 \"본국 정당 가져오기\"를 눌러 주세요.",
  "sim.vassals.14": "본국 하원에 의석이 있는 정당이 없습니다.",
  "sim.vassals.15": "\"{name}\" {name2}의 정당 {parties}개를 지우고 본국 하원 정당(지지율은 본국 의석 비율)으로 바꾼 뒤 선거를 치릅니다. 계속하시겠습니까?",
  "sim.vassals.16": "아직 의석이 없습니다 — \"선거 실시\"를 누르거나 정당별 의석을 직접 적으세요.",
  "sim.vassals.17": "\"{name}\"을(를) 본국에 합병합니다. 그 땅 {keys}곳(지역구 의석 {seats}석)은 일반 지역구가 되어 본국 선거 · 의석에 들어가고, {name2}는 해산됩니다. 계속하시겠습니까?",
  "sim.vassals.18": "세계 › 국가 순위에도 올라갑니다.",
  "sim.vassals.19": "\"{name}\"을(를) 해방합니다. 독립국이 되어 본국에서 떨어져 나가고, 그 땅 {keys}곳은 계속 본국 선거에서 빠집니다.{HemiHistory} 계속하시겠습니까?",
  "sim.vassals.20": "독립국 \"{name}\"의 땅 {keys}곳을 본국 지역구에서 아예 뺍니다 (지도에는 지역구가 아닌 땅으로 남음). 계속하시겠습니까?",
  "sim.vassals.21": "\"{name}\"을(를) 지웁니다. 칠한 땅 {v}곳은 본국 지역구로 돌아가고 의회 정보도 사라집니다. 계속하시겠습니까?",
