  "sim.vassals.61": "본국에 딸린 나라 — 지도에 그 나라 색 점무늬로 따로 보이고, 본국 선거 · 의석에서 빠집니다 (\"본국 총선에도 참여\"를 켜면 자치 지역처럼 본국 선거에도 들어감). 종속국마다 따로 의회(의석 · 정당 · 선거)가 있고, 본국에 합병하거나 해방(독립)시킬 수 있습니다.",
