  "sim.vassals.73": "오른쪽 지도에서 종속국 땅을 눌러 본국 지역구로 돌립니다. 다시 \"지우는 중\"을 누르면 끝납니다.",
  "sim.vassals.74": "오른쪽 지도에서 지역구를 차례로 눌러 \"{name}\" 땅으로 칠합니다 (같은 나라로 칠한 곳을 다시 누르면 지움). 다시 \"칠하는 중\"을 누르면 끝납니다.",
  "sim.vassals.75": "\"칠하기\"를 누른 뒤 오른쪽 지도에서 지역구를 차례로 눌러 그 나라 땅으로 정하세요. 칠하기 도구를 끈 채 지역구를 누르면 아래에서 종속국을 고를 수 있습니다.",
  "sim.vassals.76": "종속국을 추가하고 \"칠하기\"로 오른쪽 지도에서 그 나라 땅을 칠하세요.",
