  "sim.vassals.90": "경선 득표 = 그 지역의 연대 정당 지지 {mix}% + 일반 유권자 여론조사(유동층 — 전국 지지율 × 친화도) {mix2}%. 지금 무당파 {swingPct}%. 경선을 치르면 승복 효과로 결집률 +5%p.",
  "sim.vassals.91": "권역 · 지역구마다 연대 안에서 지지율이 가장 높은 정당이 후보가 돼요.",
