  "map.main.1": "제작물 목록으로",
  "map.main.2": "← 제작물 목록",
  "map.main.3": "SVG · 그림(webp · png · jpg · bmp, 자동 추적) · .jsx · .hemimap 지도를 지역구 지도(.jsx — 모양만) 또는 지역구 프리셋(.hemimap — 모양 · 이름 · 약칭 · 의석 수 · 인구)으로 — 만든 파일은 국가 › 지역구 지도에서 불러옵니다",
  "map.main.4": "SVG · 그림(webp · png · jpg · bmp) · 맵 메이커가 만든 .jsx · 지역구 프리셋 .hemimap",
  "map.main.5": "⬆ 지도 열기",
  "map.main.6": "프로젝트 저장",
  "map.main.7": "연 지도와 목록을 모두 비웁니다",
  "map.main.8": "프로젝트 이름",
  "map.main.9": "지도를 열면 자동 저장됩니다.",
  "map.main.10": "스크롤: 확대 · 축소 · 휠 클릭 드래그: 이동 · 클릭: 선택",
  "map.main.11": "SVG 도형의 id · label을 지역구 이름으로 씁니다 (끄면 도형 순서대로 이름)",
  "map.main.12": "id/label 우선 사용",
  "map.main.13": "그림 자동 추적",
  "map.main.14": "화소마다 색을 정확히 칠한 작은 지도(프로빈스 맵 등) — 색이 정확히 같은 화소끼리 한 지역으로, 키우거나 작은 조각을 지우거나 경계를 다듬지 않고 화소 경계 그대로 땀. 그림을 열면 알아서 켜짐",
  "map.main.15": "픽셀 지도",
  "map.main.16": "픽셀 지도에서 같은 색 화소는 떨어져 있어도(섬 · 월경지) 한 지역으로 — 색마다 지역 하나인 프로빈스 맵이면 켜세요. 끄면 이어진 덩어리마다 따로",
  "map.main.17": "같은 색은 떨어져도 한 지역",
  "map.main.18": "색이 이만큼 달라도 같은 지역으로 묶습니다. 움직임을 멈추면 자동으로 다시 추적합니다 — 잘게 쪼개지면 올리고, 이웃이 합쳐지면 내리세요",
  "map.main.19": "색 허용 오차",
  "map.main.20": "이보다 작은 덩어리(글자 · 번진 가장자리)는 이웃 지역에 붙임 — 그림 넓이 대비 천분율",
  "map.main.21": "최소 크기",
  "map.main.22": "그림 가장자리를 두른 큰 덩어리(바다 · 바탕)를 도형에서 뺌",
  "map.main.23": "바탕 빼기",
  "map.main.24": "검은 선 없이 같은 색으로 맞닿은 조각(압축 얼룩 · 색이 살짝 다른 옅은 선으로 갈라진 조각)을 하나로 — 검은 선으로 나뉜 곳은 합치지 않음. 끄면 조각대로 둠",
  "map.main.25": "같은 색 이웃 합치기",
  "map.main.26": "다시 추적",
  "map.main.27": "① ⬆ 지도 열기(바로 분석) → ② 오른쪽 목록에서 이름 · 약칭 · 의석 수 · 인구 고치기 · 고르기 → ③ 내보내기(.jsx — 모양만) 또는 지역구 프리셋(.hemimap — 모양 · 이름 · 의석 · 인구)",
  "map.main.28": "SVG가 가장 정확합니다. webp · png · jpg · bmp 같은 그림은 화소라 도형이 없어서, 같은 색 덩어리를 따라 도형을 자동으로 만들어요 (경계선이 뚜렷하고 지역마다 색이 다른 지도일수록 잘 됨). 맵 메이커로 만든 .jsx도 다시 열어 고칠 수 있어요",
  "map.main.29": "떨어진 땅 여러 곳이 도형 하나로 묶여 있으면 목록의 ✂로 나누고, 같은 지역구는 골라서 합치세요",
  "map.main.30": "지역구 목록",
  "map.main.31": "도형",
  "map.main.32": "· 고름",
  "map.main.33": "고른 도형들을 지역구 하나로 합칩니다",
  "map.main.34": "합치기",
  "map.main.35": "목록의 지역구마다 약칭 · 의석 수 · 인구 칸을 보이기 (지역구 프리셋 .hemimap에 담김)",
  "map.main.36": "약칭 · 의석 · 인구 칸 보이기",
  "map.main.37": "내보낼 때 쓸 파일 이름 (.hemimap · .jsx · .svg는 자동으로 붙음)",
