  "map.main.40": "모든 지역구를 지역구 프리셋(.hemimap)으로 — 지도 모양에 이름 · 약칭 · 의석 수 · 인구까지 담겨, 게임의 국가 › 지역구 지도 업로드 칸에 올리면 한 번에 들어옵니다",
